import{_ as d,o as r,c as e,a6 as a}from"./chunks/framework.B_q3ZJNF.js";const T=JSON.parse('{"title":"术语表","description":"","frontmatter":{"title":"术语表"},"headers":[],"relativePath":"proxy-software-course/glossary.md","filePath":"proxy-software-course/docs/glossary.md"}'),o={name:"proxy-software-course/glossary.md"};function s(n,t,l,p,c,i){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>本页汇总全书出现的全部术语，来自课程事实源 <code>bible.json</code>，不做额外补充或删减。</p><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>定义</th></tr></thead><tbody><tr><td>正向代理</td><td>forward proxy</td><td>代表客户端连接目标服务器的中间程序，目标服务器直接看到的是代理的连接。</td></tr><tr><td>反向代理</td><td>reverse proxy</td><td>代表服务端接收客户端连接的中间程序，客户端通常把它当成目标站点。</td></tr><tr><td>系统代理</td><td>system proxy</td><td>操作系统提供给愿意遵守该设置的应用的代理地址，不会自动截获所有流量。</td></tr><tr><td>TUN</td><td>—</td><td>向用户态程序交付 IP 包的虚拟网络接口，可承接不懂 HTTP 或 SOCKS 的应用流量。</td></tr><tr><td>数据面</td><td>data plane</td><td>逐条处理连接和字节的路径：接入、判断、拨号、转发。</td></tr><tr><td>控制面</td><td>control plane</td><td>管理配置、规则、节点、健康状态和界面的路径。</td></tr><tr><td>absolute-form</td><td>—</td><td>HTTP 代理请求行携带完整 URL 的目标形式，例如 GET <a href="http://host/path" target="_blank" rel="noreferrer">http://host/path</a> HTTP/1.1。</td></tr><tr><td>origin-form</td><td>—</td><td>发给源站的 HTTP 请求目标形式，只携带路径与查询字符串。</td></tr><tr><td>CONNECT 隧道</td><td>—</td><td>HTTP 客户端请求代理连接指定 host:port，成功后双方把该 TCP 连接当成不解释内容的字节隧道。</td></tr><tr><td>TLS 端到端</td><td>—</td><td>TLS 会话建立在客户端与目标服务之间，普通隧道代理只搬运密文，不持有解密密钥。</td></tr><tr><td>SOCKS5</td><td>—</td><td>RFC 1928 定义的通用代理协议，在 TCP 连接上协商方法并提交目标地址与命令。</td></tr><tr><td>方法协商</td><td>method negotiation</td><td>SOCKS5 客户端先列出认证方法，服务端选择一种双方都支持的方法。</td></tr><tr><td>地址类型</td><td>ATYP</td><td>SOCKS5 地址帧用来区分 IPv4、域名和 IPv6 的一个字节。</td></tr><tr><td>字节流</td><td>byte stream</td><td>TCP 交付有序字节，但不保留发送端每次 write 的消息边界。</td></tr><tr><td>TCP 分片</td><td>—</td><td>一段应用协议数据可能分多次到达；接收端必须按长度或分隔符累计到完整字段。</td></tr><tr><td>背压</td><td>backpressure</td><td>写入方跟不上时暂停读取，避免待发送数据在内存里无界增长。</td></tr><tr><td>半关闭</td><td>half-close</td><td>TCP 的一个方向已经发送 FIN，另一个方向仍可继续传输。</td></tr><tr><td>连接元数据</td><td>connection metadata</td><td>路由决策可使用的目标域名、解析后 IP、端口和入口等信息。</td></tr><tr><td>首条命中</td><td>first match</td><td>规则从上到下判断，第一条满足条件的规则立即成为最终决策。</td></tr><tr><td>域名标签边界</td><td>—</td><td>域名中点号分隔的层级边界；example.com 可匹配 a.example.com，但不应匹配 evil-example.com。</td></tr><tr><td>CIDR</td><td>—</td><td>用网络地址和前缀长度表示一段连续 IP 空间的记法，例如 10.0.0.0/8。</td></tr><tr><td>DNS 解析位置</td><td>—</td><td>域名究竟在本地代理、上游代理还是目标侧被换成 IP；它决定谁能看到查询以及哪些 IP 规则可用。</td></tr><tr><td>preserve-domain</td><td>—</td><td>先保留域名做规则判断；直连时本地解析，经上游代理时把域名交给上游。</td></tr><tr><td>resolve-first</td><td>—</td><td>先把域名解析成 IP，再让域名和 IP 规则共同参与判断。</td></tr><tr><td>出站适配器</td><td>outbound adapter</td><td>把统一的目标地址转换为某种拨号行为，例如直连、拒绝或连接 SOCKS5 上游。</td></tr><tr><td>代理链</td><td>proxy chain</td><td>本地代理不直接连接目标，而是把连接请求交给另一台上游代理。</td></tr><tr><td>严格配置校验</td><td>—</td><td>监听前验证配置的形状、取值和交叉引用，错误时明确失败而不静默猜测。</td></tr><tr><td>MATCH 兜底</td><td>—</td><td>规则列表末尾无条件命中的最后一条，保证每个连接都有明确决策。</td></tr><tr><td>依赖注入</td><td>dependency injection</td><td>把 DNS 解析器、拨号器和事件接收器作为参数传入，使网络副作用可替换、可测试。</td></tr><tr><td>结构化事件</td><td>structured event</td><td>带类型、消息和字段的运行记录，便于测试与排障，而不是拼接无法查询的日志句子。</td></tr><tr><td>优雅关闭</td><td>graceful shutdown</td><td>停止接受新连接、清理现有资源，再退出进程。</td></tr><tr><td>威胁模型</td><td>threat model</td><td>明确要保护的资产、可能的攻击者、入口和可接受风险。</td></tr><tr><td>开放代理</td><td>open proxy</td><td>没有可信访问边界、任何人都能借其连接任意目标的代理服务。</td></tr><tr><td>最小权限</td><td>least privilege</td><td>只开放完成任务所需的监听范围、目标范围、命令和权限。</td></tr></tbody></table>',3)])])}const m=d(o,[["render",s]]);export{T as __pageData,m as default};
